export default async (ctx, client) => {
  const CONNECTION_ID = 369; // Hardcoded to Mac Mini Chrome
  let tabId = null;

  console.log("Checking for active Revolut tab on Mac Mini...");
  const feeds = await client.feeds.readMany({ feed_ids: [313], limit: 100 });
  const tabs = feeds.output || [];

  const revolutTab = tabs.find(
    (t) =>
      t.url &&
      t.url.includes("app.revolut.com") &&
      !t.url.includes("logged-out") &&
      !t.url.includes("sso.revolut.com")
  );

  if (revolutTab) {
    const match = revolutTab.origin_id.match(/tab-(\d+)/);
    if (match) {
      tabId = parseInt(match[1], 10);
      console.log("Found existing Revolut tab: " + tabId);
    }
  }

  if (!tabId) {
    console.log("No active logged-in tab found. Navigating to Revolut Home...");
    const navHome = await client.operations.execute({
      connection_id: CONNECTION_ID,
      operation_key: "navigate",
      input: {
        url: "https://app.revolut.com/home",
        persistent: true,
        wait_for_load: false,
      },
    });

    tabId = navHome.output.tab_id;
    console.log("Opened Home in tab:", tabId);
    await ctx.sleep(7000);
  } else {
    console.log("Navigating existing tab to Home...");
    await client.operations.execute({
      connection_id: CONNECTION_ID,
      operation_key: "navigate",
      input: {
        url: "https://app.revolut.com/home",
        wait_for_load: false,
        tab_id: tabId,
      },
    });
    await ctx.sleep(3000);
  }

  console.log("Extracting Home data...");
  const homeRes = await client.operations.execute({
    connection_id: CONNECTION_ID,
    operation_key: "evaluate",
    input: {
      expression:
        "(() => { return { title: document.title, url: window.location.href, html: document.body.innerHTML, text: document.body.innerText }; })()",
      tab_id: tabId,
    },
  });
  const homeData = homeRes.output?.value || null;

  console.log("Navigating directly to Invest page...");
  await client.operations.execute({
    connection_id: CONNECTION_ID,
    operation_key: "navigate",
    input: {
      url: "https://app.revolut.com/invest",
      wait_for_load: false,
      tab_id: tabId,
    },
  });

  console.log("Waiting 7s for Invest view to load...");
  await ctx.sleep(7000);

  console.log("Extracting Invest data...");
  const investRes = await client.operations.execute({
    connection_id: CONNECTION_ID,
    operation_key: "evaluate",
    input: {
      expression:
        "(() => { return { title: document.title, url: window.location.href, html: document.body.innerHTML, text: document.body.innerText }; })()",
      tab_id: tabId,
    },
  });
  const investData = investRes.output?.value || null;

  console.log("Navigating directly to Transactions page...");
  await client.operations.execute({
    connection_id: CONNECTION_ID,
    operation_key: "navigate",
    input: {
      url: "https://app.revolut.com/transactions",
      wait_for_load: false,
      tab_id: tabId,
    },
  });

  console.log("Waiting 7s for Transactions view to load...");
  await ctx.sleep(7000);

  console.log("Extracting Transactions data...");
  const txRes = await client.operations.execute({
    connection_id: CONNECTION_ID,
    operation_key: "evaluate",
    input: {
      expression:
        "(() => { return { title: document.title, url: window.location.href, html: document.body.innerHTML, text: document.body.innerText }; })()",
      tab_id: tabId,
    },
  });
  const txData = txRes.output?.value || null;

  return {
    home: homeData,
    invest: investData,
    transactions: txData,
  };
};

